(()=>{"use strict";let t=self;t.addEventListener("push",i=>{if(!i.data)return;let n=i.data.json();i.waitUntil(t.registration.showNotification(n.title||"Attend",{body:n.body||"",icon:n.icon||"/icons/icon-192x192.png",badge:n.badge||"/icons/icon-192x192.png",data:{url:n.url||"/notifications"},tag:n.tag||"attend-notification"}))}),t.addEventListener("notificationclick",i=>{i.notification.close();let n=i.notification.data?.url||"/notifications";i.waitUntil(t.clients.matchAll({type:"window",includeUncontrolled:!0}).then(i=>{for(let t of i)if("focus"in t)return t.navigate(n),t.focus();return t.clients.openWindow(n)}))})})();